window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c82e4ad596bcce66"]={"versions": [{"id": "FIG-c82e4ad596bcce66", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des synchronen Sendeablaufs von XCP-Nachrichten über den CAN-Kommunikationsstack der AUTOSAR Classic Platform. Es modelliert die Schichtenbeziehung und den Kontrollfluss von der oberen Protokollschicht XCP bis zum CAN-Treiber.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten (Instanz- bzw. Modulrollen):</p>\n<ul class=\"fig-list\">\n<li><code>XCPonCAN :Xcp</code>: XCP-Modul (Transportprotokoll-Adapter für CAN)</li>\n<li><code>CanIf :CanIf</code>: CAN-Interface</li>\n<li><code>Can :Can</code>: CAN-Treiber</li>\n</ul>\n<p class=\"fig-p\">Dargestellte Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\">\n<li><code>CanIf_Transmit(Std_ReturnType, PduIdType, const PduInfoType*)</code>: Synchrone Sendeanforderung vom XCP-Modul an das CAN-Interface.</li>\n<li><code>Can_Write(Can_ReturnType, Can_HwHandleType, const Can_PduType*)</code>: Treiberfunktion zur Übergabe der PDU an die CAN-Hardwareeinheit.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><code>XCPonCAN :Xcp</code> initiiert den Sendevorgang durch synchronen Aufruf von <code>CanIf_Transmit(Std_ReturnType, PduIdType, const PduInfoType*)</code> an <code>CanIf :CanIf</code>.</li>\n<li>Während des aktiven Ausführungsfokus ruft <code>CanIf :CanIf</code> synchron <code>Can_Write(Can_ReturnType, Can_HwHandleType, const Can_PduType*)</code> auf der <code>Can :Can</code>-Instanz auf.</li>\n<li><code>Can :Can</code> schließt die Ausführung ab und liefert den Kontrollfluss via <code>Can_Write()</code> an <code>CanIf :CanIf</code> zurück.</li>\n<li><code>CanIf :CanIf</code> beendet seine Verarbeitung und kehrt via <code>CanIf_Transmit()</code> zu <code>XCPonCAN :Xcp</code> zurück.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Sendeaufruf ist rein abwärtsgerichtet und synchron blockierend modelliert. <code>Can_Write</code> verwendet <code>Can_ReturnType</code> zur Statusrückmeldung an das Interface, während <code>CanIf_Transmit</code> mit <code>Std_ReturnType</code> operiert. Das Diagramm zeigt ausschließlich den Sendeanstoß (<code>Transmit</code>), keine asynchronen Tx-Confirmations oder PDU-Router-Kopplungen.</p>"}, {"id": "FIG-9f2b5cebbd4d9cf8", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des synchronen Sendeablaufs von XCP-Nachrichten über den CAN-Kommunikationsstack der AUTOSAR Classic Platform. Es modelliert die Schichtenbeziehung und den Kontrollfluss von der oberen Protokollschicht XCP bis zum CAN-Treiber.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten (Instanz- bzw. Modulrollen):</p>\n<ul class=\"fig-list\">\n<li><code>XCPonCAN :Xcp</code>: XCP-Modul (Transportprotokoll-Adapter für CAN)</li>\n<li><code>CanIf :CanIf</code>: CAN-Interface</li>\n<li><code>Can :Can</code>: CAN-Treiber</li>\n</ul>\n<p class=\"fig-p\">Dargestellte Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\">\n<li><code>CanIf_Transmit(Std_ReturnType, PduIdType, const PduInfoType*)</code>: Synchrone Sendeanforderung vom XCP-Modul an das CAN-Interface.</li>\n<li><code>Can_Write(Can_ReturnType, Can_HwHandleType, const Can_PduType*)</code>: Treiberfunktion zur Übergabe der PDU an die CAN-Hardwareeinheit.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><code>XCPonCAN :Xcp</code> initiiert den Sendevorgang durch synchronen Aufruf von <code>CanIf_Transmit(Std_ReturnType, PduIdType, const PduInfoType*)</code> an <code>CanIf :CanIf</code>.</li>\n<li>Während des aktiven Ausführungsfokus ruft <code>CanIf :CanIf</code> synchron <code>Can_Write(Can_ReturnType, Can_HwHandleType, const Can_PduType*)</code> auf der <code>Can :Can</code>-Instanz auf.</li>\n<li><code>Can :Can</code> schließt die Ausführung ab und liefert den Kontrollfluss via <code>Can_Write()</code> an <code>CanIf :CanIf</code> zurück.</li>\n<li><code>CanIf :CanIf</code> beendet seine Verarbeitung und kehrt via <code>CanIf_Transmit()</code> zu <code>XCPonCAN :Xcp</code> zurück.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Sendeaufruf ist rein abwärtsgerichtet und synchron blockierend modelliert. <code>Can_Write</code> verwendet <code>Can_ReturnType</code> zur Statusrückmeldung an das Interface, während <code>CanIf_Transmit</code> mit <code>Std_ReturnType</code> operiert. Das Diagramm zeigt ausschließlich den Sendeanstoß (<code>Transmit</code>), keine asynchronen Tx-Confirmations oder PDU-Router-Kopplungen.</p>"}, {"id": "FIG-f8dcc1d37f8c57ae", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des synchronen Sendeablaufs von XCP-Nachrichten über den CAN-Kommunikationsstack der AUTOSAR Classic Platform. Es modelliert die Schichtenbeziehung und den Kontrollfluss von der oberen Protokollschicht XCP bis zum CAN-Treiber.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten (Instanz- bzw. Modulrollen):</p>\n<ul class=\"fig-list\">\n<li><code>XCPonCAN :Xcp</code>: XCP-Modul (Transportprotokoll-Adapter für CAN)</li>\n<li><code>CanIf :CanIf</code>: CAN-Interface</li>\n<li><code>Can :Can</code>: CAN-Treiber</li>\n</ul>\n<p class=\"fig-p\">Dargestellte Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\">\n<li><code>CanIf_Transmit(Std_ReturnType, PduIdType, const PduInfoType*)</code>: Synchrone Sendeanforderung vom XCP-Modul an das CAN-Interface.</li>\n<li><code>Can_Write(Std_ReturnType, Can_HwHandleType, const Can_PduType*)</code>: Treiberfunktion zur Übergabe der PDU an die CAN-Hardwareeinheit.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><code>XCPonCAN :Xcp</code> initiiert den Sendevorgang durch synchronen Aufruf von <code>CanIf_Transmit(Std_ReturnType, PduIdType, const PduInfoType*)</code> an <code>CanIf :CanIf</code>.</li>\n<li>Während des aktiven Ausführungsfokus ruft <code>CanIf :CanIf</code> synchron <code>Can_Write(Std_ReturnType, Can_HwHandleType, const Can_PduType*)</code> auf der <code>Can :Can</code>-Instanz auf.</li>\n<li><code>Can :Can</code> schließt die Ausführung ab und liefert den Kontrollfluss via <code>Can_Write()</code> an <code>CanIf :CanIf</code> zurück.</li>\n<li><code>CanIf :CanIf</code> beendet seine Verarbeitung und kehrt via <code>CanIf_Transmit()</code> zu <code>XCPonCAN :Xcp</code> zurück.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Sendeaufruf ist rein abwärtsgerichtet und synchron blockierend modelliert. <code>Can_Write</code> verwendet <code>Std_ReturnType</code> zur Statusrückmeldung an das Interface, konsistent mit dem Rückgabetyp von <code>CanIf_Transmit</code>. Das Diagramm zeigt ausschließlich den Sendeanstoß (<code>Transmit</code>), keine asynchronen Tx-Confirmations oder PDU-Router-Kopplungen.</p>"}, {"id": "FIG-5fba4946860457a3", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des synchronen Sendeablaufs von XCP-Nachrichten über den CAN-Kommunikationsstack der AUTOSAR Classic Platform. Es modelliert die Schichtenbeziehung und den Kontrollfluss von der oberen Protokollschicht XCP bis zum CAN-Treiber.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten (Instanz- bzw. Modulrollen):</p>\n<ul class=\"fig-list\">\n<li><code>XCPonCAN: Xcp</code>: XCP-Modul (Transportprotokoll-Adapter für CAN)</li>\n<li><code>CanIf: CanIf</code>: CAN-Interface</li>\n<li><code>Can: Can</code>: CAN-Treiber</li>\n</ul>\n<p class=\"fig-p\">Dargestellte Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\">\n<li><code>CanIf_Transmit(Std_ReturnType, PduIdType, const PduInfoType*)</code>: Synchrone Sendeanforderung vom XCP-Modul an das CAN-Interface.</li>\n<li><code>Can_Write(Std_ReturnType, Can_HwHandleType, const Can_PduType*)</code>: Treiberfunktion zur Übergabe der PDU an die CAN-Hardwareeinheit.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><code>XCPonCAN: Xcp</code> initiiert den Sendevorgang durch synchronen Aufruf von <code>CanIf_Transmit(Std_ReturnType, PduIdType, const PduInfoType*)</code> an <code>CanIf: CanIf</code>.</li>\n<li>Während des aktiven Ausführungsfokus ruft <code>CanIf: CanIf</code> synchron <code>Can_Write(Std_ReturnType, Can_HwHandleType, const Can_PduType*)</code> auf der <code>Can: Can</code>-Instanz auf.</li>\n<li><code>Can: Can</code> schließt die Ausführung ab und liefert den Kontrollfluss via <code>Can_Write()</code> an <code>CanIf: CanIf</code> zurück.</li>\n<li><code>CanIf: CanIf</code> beendet seine Verarbeitung und kehrt via <code>CanIf_Transmit()</code> zu <code>XCPonCAN: Xcp</code> zurück.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Sendeaufruf ist rein abwärtsgerichtet und synchron blockierend modelliert. <code>Can_Write</code> verwendet <code>Std_ReturnType</code> zur Statusrückmeldung an das Interface, konsistent mit dem Rückgabetyp von <code>CanIf_Transmit</code>. Das Diagramm zeigt ausschließlich den Sendeanstoß (<code>Transmit</code>), keine asynchronen Tx-Confirmations oder PDU-Router-Kopplungen.</p>"}, {"id": "FIG-fc1a945b173c203f", "releases": ["R20-11", "R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des synchronen Sendeablaufs von XCP-Nachrichten über den CAN-Kommunikationsstack der AUTOSAR Classic Platform. Es modelliert die Schichtenbeziehung und den Kontrollfluss von der oberen Protokollschicht XCP bis zum CAN-Treiber.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten (Instanz- bzw. Modulrollen):</p>\n<ul class=\"fig-list\">\n<li><code>XCPonCAN: Xcp</code>: XCP-Modul (Transportprotokoll-Adapter für CAN)</li>\n<li><code>CanIf: CanIf</code>: CAN-Interface</li>\n<li><code>Can: Can</code>: CAN-Treiber</li>\n</ul>\n<p class=\"fig-p\">Dargestellte Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\">\n<li><code>CanIf_Transmit(Std_ReturnType, PduIdType, const PduInfoType*)</code>: Synchrone Sendeanforderung vom XCP-Modul an das CAN-Interface.</li>\n<li><code>Can_Write(Std_ReturnType, Can_HwHandleType, const Can_PduType*)</code>: Treiberfunktion zur Übergabe der PDU an die CAN-Hardwareeinheit.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><code>XCPonCAN: Xcp</code> initiiert den Sendevorgang durch synchronen Aufruf von <code>CanIf_Transmit(Std_ReturnType, PduIdType, const PduInfoType*)</code> an <code>CanIf: CanIf</code>.</li>\n<li>Während des aktiven Ausführungsfokus ruft <code>CanIf: CanIf</code> synchron <code>Can_Write(Std_ReturnType, Can_HwHandleType, const Can_PduType*)</code> auf der <code>Can: Can</code>-Instanz auf.</li>\n<li><code>Can: Can</code> schließt die Ausführung ab und liefert den Kontrollfluss via <code>Can_Write()</code> an <code>CanIf: CanIf</code> zurück.</li>\n<li><code>CanIf: CanIf</code> beendet seine Verarbeitung und kehrt via <code>CanIf_Transmit()</code> zu <code>XCPonCAN: Xcp</code> zurück.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Sendeaufruf ist rein abwärtsgerichtet und synchron blockierend modelliert. <code>Can_Write</code> verwendet <code>Std_ReturnType</code> zur Statusrückmeldung an das Interface, konsistent mit dem Rückgabetyp von <code>CanIf_Transmit</code>. Das Diagramm zeigt ausschließlich den Sendeanstoß (<code>Transmit</code>), keine asynchronen Tx-Confirmations oder PDU-Router-Kopplungen.</p>"}, {"id": "FIG-44e227008c8ffea9", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des synchronen Sendeablaufs von XCP-Nachrichten über den CAN-Kommunikationsstack der AUTOSAR Classic Platform. Es modelliert die Schichtenbeziehung und den Kontrollfluss von der oberen Protokollschicht XCP bis zum CAN-Treiber.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten (Instanz- bzw. Modulrollen):</p>\n<ul class=\"fig-list\">\n<li><code>XCPonCAN: Xcp</code>: XCP-Modul (Transportprotokoll-Adapter für CAN)</li>\n<li><code>CanIf: CanIf</code>: CAN-Interface</li>\n<li><code>Can: Can</code>: CAN-Treiber</li>\n</ul>\n<p class=\"fig-p\">Dargestellte Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\">\n<li><code>CanIf_Transmit(Std_ReturnType, PduIdType, const PduInfoType*)</code>: Synchrone Sendeanforderung vom XCP-Modul an das CAN-Interface.</li>\n<li><code>Can_Write(Std_ReturnType, Can_HwHandleType, const Can_PduType*)</code>: Treiberfunktion zur Übergabe der PDU an die CAN-Hardwareeinheit.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><code>XCPonCAN: Xcp</code> initiiert den Sendevorgang durch synchronen Aufruf von <code>CanIf_Transmit(Std_ReturnType, PduIdType, const PduInfoType*)</code> an <code>CanIf: CanIf</code>.</li>\n<li>Während des aktiven Ausführungsfokus ruft <code>CanIf: CanIf</code> synchron <code>Can_Write(Std_ReturnType, Can_HwHandleType, const Can_PduType*)</code> auf der <code>Can: Can</code>-Instanz auf.</li>\n<li><code>Can: Can</code> schließt die Ausführung ab und liefert den Kontrollfluss via <code>Can_Write()</code> an <code>CanIf: CanIf</code> zurück.</li>\n<li><code>CanIf: CanIf</code> beendet seine Verarbeitung und kehrt via <code>CanIf_Transmit()</code> zu <code>XCPonCAN: Xcp</code> zurück.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Sendeaufruf ist rein abwärtsgerichtet und synchron blockierend modelliert. <code>Can_Write</code> verwendet <code>Std_ReturnType</code> zur Statusrückmeldung an das Interface, konsistent mit dem Rückgabetyp von <code>CanIf_Transmit</code>. Das Diagramm zeigt ausschließlich den Sendeanstoß (<code>Transmit</code>), keine asynchronen Tx-Confirmations oder PDU-Router-Kopplungen.</p>"}, {"id": "FIG-b4e445ca49822348", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des Sendeablaufs und der anschließenden Sendebestätigung (Tx Confirmation) von XCP-Nachrichten über den PDU-Router und CAN-Stack der AUTOSAR Classic Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten:</p>\n<ul class=\"fig-list\">\n<li><code>XCPonCAN: Xcp</code>: XCP-Modul auf CAN</li>\n<li><code>PduR - LSduR</code>: PDU-Router (Routingpfad für lineare SDU bzw. Kommunikationsinterface)</li>\n<li><code>«module» CanIf</code>: CAN-Interface-Modul</li>\n<li><code>«module» Can</code>: CAN-Treiber-Modul mit Bussymbol</li>\n</ul>\n<p class=\"fig-p\">Dargestellte Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\">\n<li><code>PduR_XcpTransmit()</code>: Sendeanforderung von Xcp an den PduR.</li>\n<li><code>CanIf_Transmit()</code>: Weiterleitung der Sendeanforderung vom PduR an CanIf.</li>\n<li><code>Can_Write()</code>: Treiberaufruf zur Hardware-Übertragung durch CanIf.</li>\n<li><code>CanIf_TxConfirmation()</code>: Bestätigungsmeldung vom CAN-Treiber an CanIf.</li>\n<li><code>LSduR_CanIfTxConfirmation()</code>: Weiterleitung der Bestätigung von CanIf an PduR.</li>\n<li><code>Xcp_TxConfirmation()</code>: Finale Sendebestätigung von PduR an Xcp.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Sendesequenz:</p>\n<ol class=\"fig-list\">\n<li><code>XCPonCAN: Xcp</code> ruft synchron <code>PduR_XcpTransmit()</code> auf <code>PduR - LSduR</code> auf.</li>\n<li><code>PduR - LSduR</code> ruft synchron <code>CanIf_Transmit()</code> auf <code>«module» CanIf</code> auf.</li>\n<li><code>«module» CanIf</code> ruft synchron <code>Can_Write()</code> auf <code>«module» Can</code> auf.</li>\n<li>Der Kontrollfluss kehrt kaskadierend über die Return-Pfeile von <code>Can_Write()</code>, <code>CanIf_Transmit()</code> und <code>PduR_XcpTransmit()</code> zurück.</li>\n</ol>\n<p class=\"fig-p\">Bestätigungssequenz (Tx Confirmation):</p>\n<ol class=\"fig-list\">\n<li>Zeitlich nachgelagert ruft <code>«module» Can</code> <code>CanIf_TxConfirmation()</code> auf <code>«module» CanIf</code> auf.</li>\n<li><code>«module» CanIf</code> ruft <code>LSduR_CanIfTxConfirmation()</code> auf <code>PduR - LSduR</code> auf.</li>\n<li><code>PduR - LSduR</code> ruft <code>Xcp_TxConfirmation()</code> auf <code>XCPonCAN: Xcp</code> auf.</li>\n<li>Die Rückmeldungen werden über die entsprechenden gestrichelten Return-Pfeile quittiert.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Kommunikationsarchitektur entkoppelt XCP und CanIf normativ über den PDU-Router (<code>PduR_XcpTransmit</code> / <code>LSduR_CanIfTxConfirmation</code>). Das Diagramm spezifiziert sowohl den Hinweg (Sendeanforderung) als auch den vollständigen Rückmeldeweg der asynchronen Sendebestätigung (<code>TxConfirmation</code>) durch alle beteiligten Zwischenschichten.</p>"}, {"id": "FIG-bb3775eecf80d29c", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des Sendeablaufs und der anschließenden Sendebestätigung (Tx Confirmation) von XCP-Nachrichten über den PDU-Router und CAN-Stack der AUTOSAR Classic Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten:</p>\n<ul class=\"fig-list\">\n<li><code>XCPonCAN: Xcp</code>: XCP-Modul auf CAN</li>\n<li><code>PduR - LSduR</code>: PDU-Router (Routingpfad für lineare SDU bzw. Kommunikationsinterface)</li>\n<li><code>«module» CanIf</code>: CAN-Interface-Modul</li>\n<li><code>«module» Can</code>: CAN-Treiber-Modul mit Bussymbol</li>\n</ul>\n<p class=\"fig-p\">Dargestellte Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\">\n<li><code>PduR_XcpTransmit()</code>: Sendeanforderung von Xcp an den PduR.</li>\n<li><code>CanIf_Transmit()</code>: Weiterleitung der Sendeanforderung vom PduR an CanIf.</li>\n<li><code>Can_Write()</code>: Treiberaufruf zur Hardware-Übertragung durch CanIf.</li>\n<li><code>CanIf_TxConfirmation()</code>: Bestätigungsmeldung vom CAN-Treiber an CanIf.</li>\n<li><code>LSduR_CanIfTxConfirmation()</code>: Weiterleitung der Bestätigung von CanIf an PduR.</li>\n<li><code>Xcp_TxConfirmation()</code>: Finale Sendebestätigung von PduR an Xcp.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Sendesequenz:</p>\n<ol class=\"fig-list\">\n<li><code>XCPonCAN: Xcp</code> ruft synchron <code>PduR_XcpTransmit()</code> auf <code>PduR - LSduR</code> auf.</li>\n<li><code>PduR - LSduR</code> ruft synchron <code>CanIf_Transmit()</code> auf <code>«module» CanIf</code> auf.</li>\n<li><code>«module» CanIf</code> ruft synchron <code>Can_Write()</code> auf <code>«module» Can</code> auf.</li>\n<li>Der Kontrollfluss kehrt kaskadierend über die Return-Pfeile von <code>Can_Write()</code>, <code>CanIf_Transmit()</code> und <code>PduR_XcpTransmit()</code> zurück.</li>\n</ol>\n<p class=\"fig-p\">Bestätigungssequenz (Tx Confirmation):</p>\n<ol class=\"fig-list\">\n<li>Zeitlich nachgelagert ruft <code>«module» Can</code> <code>CanIf_TxConfirmation()</code> auf <code>«module» CanIf</code> auf.</li>\n<li><code>«module» CanIf</code> ruft <code>LSduR_CanIfTxConfirmation()</code> auf <code>PduR - LSduR</code> auf.</li>\n<li><code>PduR - LSduR</code> ruft <code>Xcp_TxConfirmation()</code> auf <code>XCPonCAN: Xcp</code> auf.</li>\n<li>Die Rückmeldungen werden über die entsprechenden gestrichelten Return-Pfeile quittiert.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Kommunikationsarchitektur entkoppelt XCP und CanIf normativ über den PDU-Router (<code>PduR_XcpTransmit</code> / <code>LSduR_CanIfTxConfirmation</code>). Das Diagramm spezifiziert sowohl den Hinweg (Sendeanforderung) als auch den vollständigen Rückmeldeweg der asynchronen Sendebestätigung (<code>TxConfirmation</code>) durch alle beteiligten Zwischenschichten.</p>"}], "trans": [{"from": "FIG-c82e4ad596bcce66", "to": "FIG-9f2b5cebbd4d9cf8", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-9f2b5cebbd4d9cf8", "to": "FIG-f8dcc1d37f8c57ae", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Schnittstelle <code>Can_Write</code>: Der Rückgabetyp wurde von <code>Can_ReturnType</code> auf <code>Std_ReturnType</code> geändert.</li>\n</ul>"}, {"from": "FIG-f8dcc1d37f8c57ae", "to": "FIG-5fba4946860457a3", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Lifeline-Header <code>XCPonCAN: Xcp</code>, <code>CanIf: CanIf</code> und <code>Can: Can</code>: Leerzeichen nach dem Doppelpunkt ergänzt (<code>: </code> statt <code>:</code>).</li>\n</ul>"}, {"from": "FIG-5fba4946860457a3", "to": "FIG-fc1a945b173c203f", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-fc1a945b173c203f", "to": "FIG-44e227008c8ffea9", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-44e227008c8ffea9", "to": "FIG-b4e445ca49822348", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Kommunikationsarchitektur: Zwischen <code>XCPonCAN: Xcp</code> und <code>CanIf</code> wurde das Modul <code>PduR - LSduR</code> eingefügt.</li>\n<li>Lifeline-Header: Bei <code>CanIf</code> und <code>Can</code> wurde das Stereotyp <code>«module»</code> hinzugefügt; bei <code>Can</code> wurde zudem ein Bus-Symbol ergänzt.</li>\n<li>Aufruf-Sequenz Senden: Statt des direkten Aufrufs <code>CanIf_Transmit(...)</code> ruft <code>XCPonCAN: Xcp</code> nun <code>PduR_XcpTransmit()</code> auf, woraufhin <code>PduR - LSduR</code> die Funktion <code>CanIf_Transmit()</code> aufruft.</li>\n<li>Aufruf-Signaturen: Die Parameterlisten bei <code>CanIf_Transmit()</code> und <code>Can_Write()</code> wurden im Diagramm auf leere Klammern <code>()</code> verkürzt.</li>\n<li>Bestätigungspfad (TxConfirmation): Eine asynchrone Rückmeldesequenz von <code>Can</code> über <code>CanIf_TxConfirmation()</code> an <code>CanIf</code>, weiter über <code>LSduR_CanIfTxConfirmation()</code> an <code>PduR - LSduR</code> und schließlich über <code>Xcp_TxConfirmation()</code> an <code>XCPonCAN: Xcp</code> (jeweils mit gestrichelten Return-Pfeilen) wurde hinzugefügt.</li>\n</ul>"}, {"from": "FIG-b4e445ca49822348", "to": "FIG-bb3775eecf80d29c", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
